// 1. Coleta a inteligência do Banco (Saída do RPC)
const rpcData = $('RPC - Acesso Entrada').first().json;
const ctx = rpcData.context;

// 2. Extrai a Intenção (Verificando se passou pelo Motor de Negócios)
let intent = 'general';
let decision_policies = null;

try {
    // Primeiro tentamos ver se passou pela Camada 2 (Motor de Decisão de Negócios)
    if ($('Valida Intencao e Procura anteriores').isExecuted) {
        const decisaoNode = $('Valida Intencao e Procura anteriores').first().json;
        intent = decisaoNode.decision.intent;
        decision_policies = decisaoNode.decision; 
    } 
    // Caso contrário, caiu nas regras rígidas globais (saudacao, protected, etc)
    else {
        const llmNode = $('Classificacao de Intencao').first().json;
        intent = llmNode.output[0].content[0].text.intent;
    }
} catch (e) {
    intent = 'general';
}

// 3. Mapeia o Estado de Segurança Genérico do Negócios
const isAuth = (ctx.security.session_status === 'authenticated');
const requiresAuth = (ctx.security.requires_auth === true);

// A credencial (Seja ela CPF, Email ou Chave Aleatória) já mora aqui:
const sessionIdentifier = ctx.security.session_identifier || null;

// 4. Varredura de Ferramentas (Tools) disponíveis
const mainTools = ctx.agent.tools || [];
const subAgents = ctx.agent.sub_agents || [];

// Identifica se a Base tem um porteiro configurado
const hasGatekeeperTools = subAgents.some(sa => sa.is_gatekeeper && sa.tools && sa.tools.length > 0);
const hasMainTools = mainTools.length > 0;

// ============================================
// MAGIA DO ROTEADOR MULTI-TENANT (should_use_tools)
// ============================================
let should_use_tools = false;

if (!isAuth && requiresAuth) {
    // SITUAÇÃO A: Exige autenticação e ele NÃO está logado.
    // Ativamos o Porteiro.
    should_use_tools = hasGatekeeperTools; 
} else {
    // SITUAÇÃO B: Usuário já se Autenticou (Gate aberto) OU Empresa é Pública.
    // Liberamos as Tools Principais se for uma intenção 'protected' (Global) 
    // OU se a inteligência de negócios liberou ações ('allowed_actions')
    if (intent === 'protected' || (decision_policies && decision_policies.allowed_actions.length > 0)) {
        should_use_tools = hasMainTools; 
    } else {
        should_use_tools = false; // Conversa fútil. Economiza tokens de Tool Binding.
    }
}
// ============================================

// 5. Montagem do Contexto (Que serve para o CPF quanto pro Email de qualquer tenant)
let contextText = `\n\n[INSTRUÇÃO DE SEGURANÇA E SISTEMA]: `;

if (isAuth) {
    contextText += `USUÁRIO AUTENTICADO.
    - session_identifier: ${sessionIdentifier}
    - p_agent_id: ${ctx.agent.id}
    - p_conversation_id: ${ctx.conversation.id}

    ATENÇÃO: Utilize o session_identifier acima como chave em suas ferramentas sempre que necessário.`;
} else {
    if (requiresAuth) {
        contextText += `USUÁRIO NÃO AUTENTICADO. 
    Aja como o Gatekeeper da segurança. Peça a identificação necessária ao usuário para liberar os dados confidenciais dele.`;
    } else {
        contextText += `MODO PÚBLICO (ATENDIMENTO LIVRE). O usuário pode transacionar e pedir informações sem precisar se identificar no sistema no momento atual.`;
    }
}

// Injetando as políticas calculadas do Motor de Negócio direto no contexto formatado (se existirem)
if (decision_policies) {
    contextText += `\n\n[DIRETRIZES DA INTENÇÃO DE NEGÓCIO ATUAL]:\n`;
    if (decision_policies.blocked_actions && decision_policies.blocked_actions.length > 0) {
        contextText += `    - AÇÕES PROIBIDAS ORAIS/FERRAMENTAS: Você NÃO DEVE oferecer, sugerir ou acionar nada que envolva as seguintes ações: ${decision_policies.blocked_actions.join(', ')}.\n`;
    }
    if (decision_policies.fixed_response_inject) {
        contextText += `    - OBRIGAÇÃO NARRATIVA: Incorpore OBRIGATORIAMENTE a seguinte mensagem/link na sua resposta orgânica ao usuário: "${decision_policies.fixed_response_inject}"\n`;
    }
}

// 6. Saída Purificada e Agnóstica
return [{ 
    json: { 
        strategies_context: contextText,
        detected_intent: intent,
        should_use_tools: should_use_tools,
        session_identifier: sessionIdentifier,
        auth_status: isAuth ? 'active' : 'none',
        business_policies: decision_policies // Repassamos caso algum nó futuro queira logar
    } 
}];

