// 1. Prioridade Máxima: Banimento (Rigor)
if (gov.user_banned) {
    msg = "⚠️ *Acesso Restrito*\n\nIdentificamos comportamentos que violam nossas diretrizes de uso. Por este motivo, seu atendimento foi suspenso temporariamente.";
} 

// 2. Prioridade de Negócio: Empresa/Agente Inativo
else if (!gov.empresa_ativa) {
    msg = "⚙️ *Manutenção de Sistema*\n\nO sistema da empresa está passando por uma atualização rápida. Por favor, tente novamente em alguns instantes.";
} 
else if (!gov.agente_ativo) {
    msg = "🤖 *Agente Indisponível*\n\nEste serviço de atendimento está pausado no momento. Em breve retornaremos!";
}

// 3. Prioridade Infra: Lotado
else if (gov.limite_atingido) {
    msg = "⏳ *Alta Demanda*\n\nUau! Temos muitas pessoas falando comigo agora. *Aguarde uns 2 minutinhos* e me mande um 'Oi' novamente para seguirmos?";
}

// 4. Caso o Agente não exista (Erro de Configuração)
else if (!gov.agente_encontrado) {
    msg = "🚫 *Falha de Configuração*\n\nNão foi possível localizar as instruções para este atendimento. (Ref: AgentNotFound)";
}

return {
    final_message: msg,
    blocking_reason: gov.user_banned ? 'BAN' : (gov.limite_atingido ? 'LIMIT' : 'MAINTENANCE')
};

parameters.description:
={{
(() => {
  const agent = $('RPC - Acesso Entrada').first()?.json?.context?.agent;

  if (!agent) return 'Erro: agent não encontrado';

  const tools = (agent.tools || [])
    .filter(t => t?.category !== 'auth' && t?.category !== 'security');

  if (tools.length === 0) {
    return 'Nenhuma ferramenta disponível para integração.';
  }

  const lista = tools
    .map(t => {
      const required = t?.parameters?.required || [];
      const properties = t?.parameters?.properties || {};

      // monta descrição dos parâmetros
      const paramsDesc = Object.entries(properties)
        .map(([key, val]) => {
          const obrigatorio = required.includes(key) ? ' (obrigatório)' : '';
          return `- ${key}${obrigatorio}: ${val.description || 'sem descrição'}`;
        })
        .join('\n');

      return `🔹 tool_name: "${t.name}"
descrição: ${t.description}

parâmetros:
${paramsDesc || 'nenhum parâmetro necessário'}
`;
    })
    .join('\n');

  return `Proxy Universal de Integrações. Use-a para consultar dados e executar ações em nome do usuário.

=== FERRAMENTAS DISPONÍVEIS ===
${lista}
=== REGRAS DE USO ===
1. Use exatamente o valor de "tool_name" listado acima.
2. Preencha apenas os parâmetros exigidos pela ferramenta escolhida.
3. Se faltar algum parâmetro obrigatório, solicite ao usuário antes de executar.
4. Nunca invente valores de parâmetros.`;
})()
}}

