// 1. Tokens do LLM principal
const usage = $json.usage || {};
const llm_prompt     = usage.input_tokens  ?? usage.prompt_tokens ?? 0;
const llm_completion = usage.output_tokens ?? usage.completion_tokens ?? 0;

// 2. Custo do Embedding (RAG)
let embedding_tokens = 0;
try {
  const embeddingUsage = $('HTTP Request - Embedings (msg usr)').first().json?.usage;
  embedding_tokens = embeddingUsage?.prompt_tokens ?? 0;
} catch(e) { embedding_tokens = 0; }

// 3. IDs de Rastreabilidade
// O traceId DEVE ser o queue_id para vincular a entrada com o custo
const queueId = $('RPC - Acesso Entrada').item.json.queue_id;
const executionId = $executionId;

// 4. Modelo
const modelId = $('Edit Fields').first().json?.agent?.modelId || 'gpt-4o-mini';

// === CONTRATO DE TELEMETRIA ATUALIZADO ===
return [{
  json: {
    event_type: "llm_usage",
    trace_id: queueId,
    idempotency_key: `${queueId}_llm_v7`, // Impede cobrança duplicada
    timestamp: new Date().toISOString(),
    tenant_id: $('Edit Fields').first().json.tenant_id,
    agent_id: $('Edit Fields').first().json.agent_id,
    model: modelId,
    usage: {
      prompt_tokens: llm_prompt + embedding_tokens,
      completion_tokens: llm_completion
    },
    metadata: {
      n8n_exec_id: executionId,
      channel: "whatsapp",
      conversation_id: $('Edit Fields').first().json["conversation.id"]
    }
  }
}];

