parameters.jsCode:
// O n8n processará o JSON anterior. Asseguramos variáveis mínimas usando Fallbacks:
const item = $input.item.json;

// 1. Pescaria da Intenção dentro do labirinto do Langchain
let intent = "outro";
try {
  // Acesso direto à saída protegida do node anterior "Classificador de Intenções - Negocio"
  intent = item.output[0].content[0].text.intent;
} catch(e) {
  // Fallback caso algum dia você use um parser purista diferente do N8N
  intent = item.intent || "outro";
}

// 2. Mock dos Status (Mais pra frente atrelaremos isso ao DB de verdade, por enquanto é estático)
const state = item.context_state || { stage: "abertura", flags: {} };
const policy = item.policies || { canDo: ["send_link", "request_cnpj"], cannotDo: [] };

// Variáveis de Decisão
let blocked_actions = [...policy.cannotDo];
let allowed_actions = [...policy.canDo];
let fixed_response_inject = null;

// ==========================================\n// 🧠 REGRAS DE ROTEAMENTO SEMIÓTICO (Intent)\n// ==========================================

// Se a intenção não denota avanço no funil, proibimos CTAs precoces
if (["duvida", "taxa", "como_funciona", "reclamacao"].includes(intent)) {
  blocked_actions.push("send_link");
  blocked_actions.push("request_cnpj");
}

// Resposta Forçada (Regra de Compliance/Gatilho Fixo)
if (intent === "como_funciona") {
  fixed_response_inject = "Vamos lá, vou te explicar melhor. Você pode optar por dar como garantia apenas o seu recebível...";
}

// ==========================================\n// 🛡️ REGRAS DE ESTADO (Loops e One-Time Actions)\n// ==========================================

if (state.flags.link_sent === true) {
  blocked_actions.push("send_link");
}

if (state.flags.cnpj_validated === true || state.flags.cnpj_requested === true) {
  blocked_actions.push("request_cnpj");
}

// Limpeza e Segurança 
let unique_blocked = [...new Set(blocked_actions)];
let unique_allowed = allowed_actions.filter(action => !unique_blocked.includes(action));

// Repassa ao "Formatar Contexto" a decisão de ouro
return {
  decision: {
    intent: intent,
    blocked_actions: unique_blocked,
    allowed_actions: unique_allowed,
    fixed_response_inject: fixed_response_inject,
    next_stage_evaluate: state.stage 
  },
  ...item 
};

